+  for (const ch of text) {
+    if (ch === "*") source += "[^/]*";
+    else if (ch === "?") source += "[^/]";
+    else source += ch.replace(/[\\^$.*+?()[\]{}|]/g, "\\$&");
+  }
+  return { globstar: false, regex: new RegExp(`^${source}$`, "u") };
+}
